def _parse_version(value):
    if not isinstance(value, str):
        raise TypeError("engine_version must be a string")
    parts = value.split(".")
    if len(parts) not in (2, 3) or any(not part.isdigit() for part in parts):
        raise ValueError("invalid engine version")
    numbers = tuple(int(part) for part in parts)
    if len(numbers) == 2:
        numbers += (0,)
    return numbers


def make_renderer(profile, engine_version):
    if not isinstance(profile, str):
        raise TypeError("profile must be a string")
    if not profile:
        raise ValueError("profile must not be empty")
    version = _parse_version(engine_version)

    if engine_version < "2.5.0":
        def render(value, saved_profile=profile):
            return saved_profile + ":" + str(value)
    else:
        def render(value, saved_profile=profile):
            return "[" + saved_profile + "] " + repr(value)
    return render

